import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    if n == 0:
        print(0)
        return

    pi = [0] * n
    z = [0] * n
    deg = [0] * n
    total = 0

    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    l, r = 0, 0
    for i in range(1, n):
        if i <= r:
            z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] - 1 > r:
            l, r = i, i + z[i] - 1

    for i in range(n):
        if pi[i] == i + 1:
            deg[i] = 1
        elif pi[i] > 0:
            half_len = pi[i]
            if half_len % 2 == 0:
                if z[half_len // 2] >= half_len:
                    deg[i] = deg[half_len - 1] + 1
                else:
                    deg[i] = 1
            else:
                deg[i] = 1
        else:
            deg[i] = 0
        total += deg[i]

    print(total)

if __name__ == "__main__":
    main()
